const rand=n=>{const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);};
export class City{
 constructor(canvas,state,mode=1){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.state=state;this.mode=mode;this.tick=0;this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('reduced');this.resize=new ResizeObserver(()=>this.size());this.resize.observe(canvas);this.size();this.draw();}
 size(){const r=this.canvas.getBoundingClientRect();this.w=r.width;this.h=r.height;const d=Math.min(devicePixelRatio||1,2);this.canvas.width=this.w*d;this.canvas.height=this.h*d;this.ctx.setTransform(d,0,0,d,0,0);if(this.reduced)this.draw();}
 stop(){cancelAnimationFrame(this.frame);this.resize.disconnect();}
 poly(points,fill,stroke){const c=this.ctx;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.stroke();}}
 project(x,y,z=0){return [this.w*.49+(x-y)*this.w*.028,this.h*.22+(x+y)*this.h*.023-z*this.h*.006];}
 block(x,y,z,lit,missing=false){const a=this.project(x,y),b=this.project(x+.78,y),c=this.project(x+.78,y+.78),d=this.project(x,y+.78),a1=this.project(x,y,z),b1=this.project(x+.78,y,z),c1=this.project(x+.78,y+.78,z),d1=this.project(x,y+.78,z);if(missing){this.poly([a,b,c,d],null,'#59787535');return;}this.poly([a,b,b1,a1],lit?'#375455':'#1a3339','#43666955');this.poly([b,c,c1,b1],lit?'#1b3d40':'#122a30','#43666955');this.poly([a1,b1,c1,d1],lit?'#56716a':'#2b474b','#63817a65');if(lit){const ctx=this.ctx;ctx.fillStyle='#f5c984';for(let j=1;j<z/2;j++){const p=this.project(x+.83,y+.2,j*1.6);ctx.fillRect(p[0]-1,p[1],2.1,2.4);}}}
 draw(){if(!this.w){this.frame=requestAnimationFrame(()=>this.draw());return;}const c=this.ctx,w=this.w,h=this.h;c.clearRect(0,0,w,h);const bg=c.createRadialGradient(w*.55,h*.48,0,w*.5,h*.5,w*.75);bg.addColorStop(0,'#193b40');bg.addColorStop(1,'#08191f');c.fillStyle=bg;c.fillRect(0,0,w,h);c.lineWidth=.7;
 for(let n=-16;n<22;n++){const a=this.project(n,-10),b=this.project(n,22);c.strokeStyle='#6d9c9120';c.beginPath();c.moveTo(...a);c.lineTo(...b);c.stroke();const d=this.project(-10,n),e=this.project(22,n);c.beginPath();c.moveTo(...d);c.lineTo(...e);c.stroke();}
 const river=[[w*.58,-30],[w*.65,h*.14],[w*.60,h*.34],[w*.43,h*.51],[w*.37,h*.73],[w*.42,h+30]];c.lineCap='round';c.lineJoin='round';c.beginPath();river.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle='#4e979e22';c.lineWidth=w*.103;c.stroke();c.strokeStyle='#143d47';c.lineWidth=w*.09;c.stroke();c.strokeStyle='#47859166';c.lineWidth=1;c.stroke();
 for(let i=0;i<95;i++){const t=(i/95+this.tick*.0006)%1,seg=Math.min(4,Math.floor(t*5)),f=t*5-seg;const x=river[seg][0]*(1-f)+river[seg+1][0]*f+(rand(i)-.5)*w*.065,y=river[seg][1]*(1-f)+river[seg+1][1]*f;c.strokeStyle='#a1d5d440';c.lineWidth=1;c.beginPath();c.moveTo(x,y);c.lineTo(x+3,y+7);c.stroke();}
 for(let sum=-2;sum<27;sum++)for(let x=-5;x<16;x++){const y=sum-x;if(y<0||y>15)continue;const [px,py]=this.project(x,y);if(px<10||px>w-10||py<h*.12||py>h*.9)continue;const t=Math.max(0,Math.min(.999,py/h)),r=river[Math.min(4,Math.floor(t*5))][0];if(Math.abs(px-r)<w*.065)continue;const east=px>w*.58&&py>h*.33;const people=this.state.peopleView||this.mode>=3;const missing=east&&!people;if(rand(x*41+y)<.19)continue;const height=3+rand(x*19+y*37)*(east?5:15);this.block(x,y,height,east&&people||rand(x*11+y)>.55,missing);}
 if(!this.state.peopleView&&this.mode===1){this.poly([[w*.65,h*.36],[w*.88,h*.43],[w*.88,h*.75],[w*.60,h*.68]],'#10282ee6','#9fa9a661');c.font=`${Math.max(11,w*.019)}px monospace`;c.textAlign='center';c.fillStyle='#91aaa6';c.fillText('UNVERIFIED RIVER MARGIN',w*.745,h*.52);c.fillStyle='#567775';c.font='10px monospace';c.fillText('OCCUPANCY: UNKNOWN',w*.745,h*.56);}
 if(this.state.peopleView||this.mode>=3){for(let i=0;i<40;i++){const x=w*(.62+rand(i*3)*.22),y=h*(.40+rand(i*5)*.27);c.fillStyle=`rgba(237,188,115,${.25+rand(i)*.5})`;c.beginPath();c.arc(x,y,1.2+(Math.sin(this.tick*.025+i)+1)*.5,0,Math.PI*2);c.fill();}}
 if(this.mode===2){c.strokeStyle='#d9ad76';c.lineWidth=3;c.setLineDash([8,6]);c.lineDashOffset=this.tick*.5;c.beginPath();c.moveTo(w*.39,h*.23);c.lineTo(w*.46,h*.42);c.lineTo(w*.76,h*.60);c.stroke();c.setLineDash([]);}
 if(this.mode===5){const [east,b1,b2]=this.state.gates;const paths=[[[.46,.20],[.58,.4],[.78,.63]],[[.46,.2],[.22,.40],[.16,.55]],[[.46,.2],[.46,.64],[.57,.79]]];paths.forEach((p,i)=>{c.beginPath();p.forEach(([x,y],k)=>k?c.lineTo(w*x,h*y):c.moveTo(w*x,h*y));c.strokeStyle=i===0&&east>25?'#e17e6f':'#83b8b0';c.lineWidth=2+[east,b1,b2][i]/10;c.setLineDash([12,8]);c.lineDashOffset=-this.tick*.65;c.stroke();c.setLineDash([]);});}
 c.textAlign='left';c.fillStyle='#9eb6b2';c.font='10px monospace';c.fillText('N ↑',22,h-27);c.fillText('NAYANTARA / FICTIONAL CITY MODEL',50,h-27);this.canvas.dataset.rendered='true';if(!this.reduced){this.tick++;this.frame=requestAnimationFrame(()=>this.draw());}}
}
export function startRain(canvas){const ctx=canvas.getContext('2d');let w=0,h=0,t=0,frame;function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight;}resize();window.addEventListener('resize',resize);function draw(){ctx.clearRect(0,0,w,h);if(!document.body.classList.contains('reduced')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){ctx.strokeStyle='#b5d3d31c';ctx.lineWidth=.65;for(let i=0;i<100;i++){const x=(rand(i)*w-t*.3+w)%w,y=(rand(i+200)*h+t*(2+rand(i)))%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-4,y+18);ctx.stroke();}t++;}frame=requestAnimationFrame(draw);}draw();return()=>cancelAnimationFrame(frame);}
